fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len() as u8; // Get the length of the original vector

    // If the original length is greater than or equal to the target width, return the original vector
    if orig_len >= width {
        return orig;
    }

    // Create a new vector with the target width
    let mut res = vec![fillchar; width as usize]; // Fill with the fill character

    // Calculate the starting index to place the original characters
    let start_index = (width - orig_len) as usize;

    // Copy the original characters into the new vector
    res[start_index..(start_index + orig_len as usize)].copy_from_slice(&orig);

    res
}